function initLogin() {
  const form = document.querySelector("#loginForm");
  if (!form) return;
  const message = document.querySelector("#loginMessage");
  const submit = form.querySelector('button[type="submit"]');
  const mfaField = document.querySelector("#mfaField");
  const mfaInput = document.querySelector("#mfaToken");
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    message.textContent = "";
    message.dataset.state = "";
    if (!form.reportValidity()) return;
    try {
      submit.disabled = true;
      submit.textContent = "Verificandoâ€¦";
      const captcha = await getRecaptchaToken("login");
      const { response, data } = await postJson(`/api/login/${form.dataset.role}`, {
        email: form.email.value.trim(),
        password: form.password.value,
        captcha,
        mfa_token: mfaInput?.value || "",
      });
      if (data.error === "mfa_required") {
        mfaField.hidden = false;
        mfaInput.required = true;
        mfaInput.focus();
        message.textContent = "Digite o cÃ³digo do seu aplicativo autenticador.";
        return;
      }
      if (!response.ok) throw new Error(data.error || "login_error");
      window.location.assign("./client-dashboard.html");
    } catch (error) {
      message.textContent = authMessages[error.message] || "NÃ£o foi possÃ­vel entrar agora. Tente novamente.";
      message.dataset.state = "error";
    } finally {
      submit.disabled = false;
      submit.textContent = "Entrar na conta";
    }
  });
}

function isStrongPassword(value) {
  return (
    value.length >= 8 &&
    value.length <= 128 &&
    /[a-z]/.test(value) &&
    /[A-Z]/.test(value) &&
    /\d/.test(value) &&
    /[^A-Za-z0-9]/.test(value)
  );
}

function initRegistration() {
  const form = document.querySelector("#registerForm");
  if (!form) return;
  const message = document.querySelector("#registerMessage");
  const submit = form.querySelector('button[type="submit"]');
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    if (submit.disabled) return;
    message.textContent = "";
    message.dataset.state = "";
    if (!form.reportValidity()) return;
    if (form.password.value !== form.confirmPassword.value) {
      message.textContent = "As senhas nÃ£o coincidem.";
      message.dataset.state = "error";
      return;
    }
    if (!isStrongPassword(form.password.value)) {
      message.textContent = authMessages.weak_password;
      message.dataset.state = "error";
      return;
    }
    try {
      submit.disabled = true;
      submit.textContent = "Criando contaâ€¦";
      form.setAttribute("aria-busy", "true");
      const fields = form.elements;
      // Independent setup requests can run together while keeping CSRF required.
      const [captcha] = await Promise.all([
        getRecaptchaToken("register"),
        fetchCsrf(),
      ]);
      const { response, data } = await postJson("/api/register", {
        name: fields.namedItem("name").value.trim(),
        email: fields.namedItem("email").value.trim(),
        password: fields.namedItem("password").value,
        acceptTerms: fields.namedItem("acceptTerms").checked,
        captcha,
      });
      if (!response.ok || data.authenticated !== true)
        throw new Error(data.error || "registration_error");
      message.textContent = "Conta criada. Abrindo sua Ã¡rea do clienteâ€¦";
      message.dataset.state = "success";
      // No email in the URL or artificial delay. The existing cart is preserved.
      window.location.replace("./client-dashboard.html");
    } catch (error) {
      message.textContent = authMessages[error.message] || "NÃ£o foi possÃ­vel criar sua conta agora.";
      message.dataset.state = "error";
    } finally {
      form.removeAttribute("aria-busy");
      if (message.dataset.state !== "success") {
        submit.disabled = false;
        submit.textContent = "Criar minha conta";
      }
    }
  });
}

