function initCompatibilityChecklist() {
  const fieldset = document.querySelector("#compatibilityChecklist");
  if (!fieldset) return;
  const boxes = [...fieldset.querySelectorAll('input[type="checkbox"]')];
  const progress = document.querySelector("#checklistProgress");
  const download = document.querySelector("#downloadChecklist");
  let started = false;
  let completed = false;
  fieldset.addEventListener("change", () => {
    const count = boxes.filter((box) => box.checked).length;
    progress.textContent = `${count} de ${boxes.length} verificaÃ§Ãµes marcadas.${count === boxes.length ? " Lista revisada. Confirme dÃºvidas sobre o produto com o suporte." : ""}`;
    if (count && !started) {
      started = true;
      trackEvent("checklist_start", { content_id: "music-software-checklist" });
    }
    if (count === boxes.length && !completed) {
      completed = true;
      trackEvent("checklist_complete", { content_id: "music-software-checklist" });
    }
  });
  download.hidden = false;
  download.addEventListener("click", () => {
    const lines = boxes.map((box) => `${box.checked ? "[x]" : "[ ]"} ${box.closest("label").textContent.trim()}`);
    const text = ["NEURAL X â€” CHECKLIST DE SOFTWARE MUSICAL", "", ...lines, "", "A lista nÃ£o testa o computador nem certifica compatibilidade.", "Confira ediÃ§Ã£o, licenÃ§a e requisitos com o fornecedor antes de pagar.", "Guia: https://neuralxplugins.com.br/checklist-software-musical.html", "Suporte: https://neuralxplugins.com.br/contact.html"].join("\n");
    const url = URL.createObjectURL(new Blob([text], { type: "text/plain;charset=utf-8" }));
    const link = document.createElement("a");
    link.href = url;
    link.download = "neural-x-checklist-software-musical.txt";
    document.body.append(link);
    link.click();
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
    const downloadData = {
      content_id: "music-software-checklist",
      file_name: "neural-x-checklist-software-musical.txt",
      file_extension: "txt",
      link_url: "https://neuralxplugins.com.br/checklist-software-musical.html",
    };
    trackEvent("checklist_download", downloadData);
    trackEvent("file_download", downloadData);
  });
}

function initRecommendation() {
  const form = document.querySelector("#recommendationForm");
  const result = document.querySelector("#recommendationResult");
  const match = document.querySelector("#recommendationMatch");
  const name = document.querySelector("#recommendationName");
  const reason = document.querySelector("#recommendationReason");
  const link = document.querySelector("#recommendationLink");
  const changeButton = document.querySelector("#changeRecommendation");
  const emailToggle = document.querySelector("#showRecommendationEmail");
  const leadForm = document.querySelector("#leadForm");
  const leadInterest = document.querySelector("#leadInterest");
  if (
    !form ||
    !result ||
    !match ||
    !name ||
    !reason ||
    !link ||
    !changeButton ||
    !emailToggle ||
    !leadForm ||
    !leadInterest
  )
    return;

  let activeRecommendation = null;
  form.addEventListener("submit", (event) => {
    event.preventDefault();
    if (!form.reportValidity()) return;
    const interest = new FormData(form).get("recommendationInterest");
    const recommendation = RECOMMENDATIONS[interest];
    if (!recommendation) return;
    const product = recommendation.productId
      ? PRODUCTS[recommendation.productId]
      : null;
    activeRecommendation = recommendation;
    match.textContent = recommendation.match;
    name.textContent = product?.name || recommendation.name;
    reason.textContent = recommendation.reason;
    link.href = recommendation.url;
    link.textContent = product ? "Conhecer produto" : "Comparar agora";
    leadInterest.value = interest;
    form.hidden = true;
    result.hidden = false;
    leadForm.hidden = true;
    emailToggle.hidden = false;
    trackEvent("view_recommendation", {
      interest,
      recommended_product: product?.id || "compare",
    });
    name.focus?.();
  });

  link.addEventListener("click", () => {
    if (activeRecommendation?.productId)
      trackOfferSelection(activeRecommendation.productId, "recommendation");
  });
  emailToggle.addEventListener("click", () => {
    leadForm.hidden = false;
    emailToggle.hidden = true;
    document.querySelector("#leadName")?.focus();
  });
  changeButton.addEventListener("click", () => {
    result.hidden = true;
    leadForm.hidden = true;
    emailToggle.hidden = false;
    form.hidden = false;
    form.querySelector('input[name="recommendationInterest"]:checked')?.focus();
  });
}

